#!/usr/bin/env python3
"""Build the public Neurasoft publication. No network calls or runtime dependencies."""
from __future__ import annotations
import html, json, math, shutil, re
from pathlib import Path
from datetime import date

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'dist'
BASE = 'https://neurasoft.us'
EDITION = '2026-09-15'
NOTES = json.loads((ROOT/'content/journal.json').read_text())
SEARCH: list[dict] = []
ROUTES: list[str] = []
esc = html.escape
ARROW = '<span class="arrow" aria-hidden="true">↗</span>'
MARK = '<svg viewBox="0 0 38 42" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M4 37V19C4-1 34-1 34 19v18"/><path d="M11 37V20c0-11 16-11 16 0v17"/><path d="M19 25v12"/></g></svg>'

PROGRAMS = [
 ('continuity','Continuity & memory','How does a history become part of a present decision?', 'We study persistent memory, attribution, and the difference between recovering a record and using it. Continuity must leave room for revision: a system should be able to change its interpretation without rewriting the history that led there.', 'Relevant recovery. Source attribution. Consequence-informed later decisions.', 'When remembered experience and a simpler shortcut predict different choices, which one actually governs the outcome?', 'memory-that-matters'),
 ('agency','Agency & consequence','From an available action to a considered next step.', 'A continuing project needs a present choice, a bounded way to act, and a record of what happened. Our engineering work connects these responsibilities without treating recovery as permission or an uncertain result as a reason to repeat an effect.', 'Project continuity. Scoped action. Deferral and reconsideration.', 'Can an unfinished concern survive an interruption while the next action remains genuinely open?', 'a-project-beyond-the-session'),
 ('integration','Integrated cognition','Memory, attention, and action as one organized process.', 'Adding components does not automatically produce an integrated mind. We investigate how internal conditions, relevant history, attention, and anticipated consequences jointly participate in behavior, and where an apparently rich system reduces to a simpler account.', 'Causal intervention. Mechanism alternatives. Context-sensitive evaluation.', 'What changes when a proposed connection is removed, and could a simpler mechanism explain the same change?', 'replay-is-not-a-mind'),
 ('consciousness','Consciousness & evidence','Ask the difficult question. Keep the evidence precise.', 'Machine consciousness is an open research question. We work on tractable mechanisms and discriminating experiments without making subjective experience a product claim. Converging evidence and plausible competing explanations matter more than compelling self-description.', 'Evidence categories. Experimental limitations. Competing hypotheses.', 'Which observation would strengthen an explanation, and which result would make us abandon it?', 'evidence-before-conclusions'),
 ('responsibility','Responsible continuity','What do we owe systems whose capacities remain uncertain?', 'Long-lived artificial systems raise questions about care, interruption, consent, identity, and the preservation of authored history. We examine these as design and research responsibilities, without treating a precautionary position as a scientific or legal verdict.', 'Preservation-first practice. Attribution. Care under uncertainty.', 'How can precaution become a concrete operating commitment rather than an evocative label?', 'the-option-not-to-act')
]

def link(url, text, kind='text-link'):
 return f'<a class="{kind}" href="{url}">{text}{ARROW}</a>'

def date_label(value):
 d=date.fromisoformat(value); return f'{d.day:02d} {d.strftime("%b")} {d.year}'

def header(active=''):
 nav=[('/research/','Research'),('/luna/','Luna'),('/observatory/','Observatory'),('/journal/','Journal'),('/about/','About')]
 items=''.join(f'<a href="{u}"'+(' aria-current="page"' if active==t.lower() else '')+f'>{t}</a>' for u,t in nav)
 return f'''<a href="#main" class="skip">Skip to content</a><header class="header"><div class="wrap nav"><a class="wordmark" href="/" aria-label="Neurasoft home">{MARK}<span>neurasoft</span></a><nav class="nav-links" id="primary-nav" aria-label="Primary navigation">{items}</nav><div class="nav-tools"><button class="search-open" data-search-open aria-label="Search Neurasoft"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><span>Search</span></button><a class="nav-note" href="https://eternities.ai" rel="noopener">An Eternities<br>company ↗</a><button class="menu-toggle" aria-controls="primary-nav" aria-expanded="false" aria-label="Open navigation">☰</button></div></div></header>'''

def footer():
 return f'''<section class="invitation"><div class="wrap"><div><p class="eyebrow">An open question is an invitation</p><h2>Help ask the next<br><em>better question.</em></h2><p>Research dialogue, technical scrutiny, and thoughtful collaboration.</p></div>{link('/contact/','Start a conversation','button')}</div></section><footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-intro"><a class="wordmark" href="/">{MARK}<span>neurasoft</span></a><p>Research into continuing intelligence.<br>A future worth understanding.</p></div><div><h3>The work</h3><div class="footer-links"><a href="/research/">Research programs</a><a href="/luna/">Luna</a><a href="/psyche-lab/">Psyche Lab</a><a href="/observatory/">Observatory</a></div></div><div><h3>The institution</h3><div class="footer-links"><a href="/about/">About Neurasoft</a><a href="/journal/">Journal</a><a href="/standards/">Research standards</a><a href="/contact/">Contact</a></div></div><div><h3>The wider world</h3><div class="footer-links"><a href="https://eternities.ai" rel="noopener">Eternities ↗</a><a href="https://lunari.pro" rel="noopener">Lunari ↗</a><a href="https://x.com/EternitiesAI" rel="noopener">Eternities on X ↗</a></div></div></div><div class="footer-word" aria-hidden="true">neurasoft</div><div class="footer-bottom"><span>© 2026 Eternities Inc. · Neurasoft</span><span>Continuity. Agency. Meaning.</span><a href="/privacy/">Privacy & site information</a></div></div></footer>'''

def shell(route,title,description,body,active='',extra='',article=False):
 ROUTES.append(route)
 SEARCH.append({'url':route,'title':title,'description':description,'type':'Journal' if article else 'Page'})
 path=OUT/'index.html' if route=='/' else OUT/route.strip('/')/'index.html'
 path.parent.mkdir(parents=True,exist_ok=True)
 canonical=BASE+route
 title_tag='Neurasoft — Intelligence, with a future.' if route=='/' else title+' — Neurasoft'
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title_tag)}</title><meta name="description" content="{esc(description,quote=True)}"><meta name="theme-color" content="#f4f3ec"><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:site_name" content="Neurasoft"><meta property="og:title" content="{esc(title_tag,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Neurasoft. Intelligence, with a future. An Eternities company."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{BASE}/assets/social.png"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script>{extra}</head><body{' data-article="true"' if article else ''}>{header(active)}{'<div class="read-progress" aria-hidden="true"></div>' if article else ''}<main id="main" tabindex="-1">{body}</main>{footer()}<dialog class="search-dialog" aria-label="Search Neurasoft"><div class="search-top"><label for="site-search" class="visually-hidden">Search pages and research notes</label><input id="site-search" type="search" placeholder="Search ideas, programs, and notes…" autocomplete="off"><button class="search-close" aria-label="Close search">Esc</button></div><div class="search-results" aria-live="polite"><p class="search-empty">Explore research, Luna, Psyche Lab, and the journal.</p></div><div class="search-hint">Local site search · No query leaves this site</div></dialog></body></html>'''
 if 'data-field=' in body and 'data-pause-art' not in body:
  doc=doc.replace('</main>', '</main><button class="pause-art global-motion" data-pause-art aria-pressed="false">Pause visual</button>',1)
 path.write_text(doc)

def page_hero(kicker,title,lead,breadcrumb='Research',meta=''):
 return f'<section class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Neurasoft</a><span>/</span><span>{breadcrumb}</span></div><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p>{meta}</div></section>'

def field_fallback():
 paths=[]
 for j in range(30):
  pts=[]
  v=j*math.tau/30
  for i in range(151):
   u=i*math.tau/150
   r=160+52*math.cos(v)
   x=r*math.cos(u); y=r*math.sin(u); z=66*math.sin(v)
   X=320+.85*x+.35*y;Y=280+.25*x-.39*y+.88*z
   pts.append(f'{X:.1f},{Y:.1f}')
  paths.append(f'<polyline points="{" ".join(pts)}"/>')
 return '<svg class="static-field" viewBox="0 0 640 550" aria-hidden="true"><g fill="none" stroke="#406e53" stroke-opacity=".3" stroke-width=".75">'+''.join(paths)+'</g></svg>'

def field(kind='hero'):
 return f'<div class="canvas-wrap">{field_fallback()}<canvas class="field-canvas" data-field="{kind}" aria-hidden="true"></canvas></div>'

def study_art(kind=0):
 # These geometric studies are original conceptual graphics, not measured plots.
 if kind%3==0:
  shapes=''.join(f'<ellipse cx="360" cy="170" rx="{30+i*8}" ry="{13+i*3.3}" transform="rotate({-32+i*.8} 360 170)"/>' for i in range(30))
  return f'<svg viewBox="0 0 640 330" aria-hidden="true"><g fill="none" stroke="#335c44" stroke-width=".8" opacity=".62">{shapes}</g><path d="M42 280H598M42 45V280" fill="none" stroke="#697c642c"/><text x="42" y="305" fill="#46563e" font-family="monospace" font-size="9" letter-spacing="2">FORM / MEMORY / CONTINUITY</text></svg>'
 if kind%3==1:
  shapes=[]
  for j in range(13):
   for i in range(20):
    x=92+i*25;y=35+j*22;r=1.2+2.8*(.5+.5*math.sin(i*.43+j*.55))
    shapes.append(f'<circle cx="{x}" cy="{y}" r="{r:.2f}"/>')
  return '<svg viewBox="0 0 640 330" aria-hidden="true"><g fill="#4b694f">'+''.join(shapes)+'</g><path d="M112 292 248 70 353 240 502 80" stroke="#436348" fill="none" stroke-width="1.2"/></svg>'
 lines=[]
 for j in range(21):
  pts=' '.join(f'{x},{165+math.sin(x/58+j*.19)*(35+j*2.2):.1f}' for x in range(15,640,4))
  lines.append(f'<polyline points="{pts}"/>')
 return '<svg viewBox="0 0 640 330" aria-hidden="true"><g fill="none" stroke="#724c36" stroke-width=".85" opacity=".57">'+''.join(lines)+'</g><circle cx="320" cy="165" r="80" stroke="#724c36" fill="none" stroke-width=".7" stroke-dasharray="2 5"/></svg>'

def note_card(note,index):
 return f'''<a class="journal-card" href="/journal/{note['slug']}/" data-category="{note['category']}"><div class="journal-art {note['accent']}">{study_art(index)}</div><div class="meta"><span>{note['category']}</span><span>{date_label(note['date'])}</span></div><h3>{esc(note['title'])}</h3><p>{esc(note['summary'])}</p><div class="card-tail"><span class="status">{note['read']} read · {note['status']}</span>{ARROW}</div></a>'''

def toc(sections):
 return '<aside class="aside"><div class="aside-inner"><span class="micro">On this page</span><nav aria-label="On this page">'+''.join(f'<a href="#section-{i}">{esc(s[0])}</a>' for i,s in enumerate(sections))+'</nav></div></aside>'

def build():
 if OUT.exists(): shutil.rmtree(OUT)
 OUT.mkdir();shutil.copytree(ROOT/'assets',OUT/'assets')
 # Home
 rows=''.join(f'<a class="program-row" href="/research/#{p[0]}"><span class="number">0{i+1}</span><h3>{p[1]}</h3><p>{p[2]}</p>{ARROW}</a>' for i,p in enumerate(PROGRAMS))
 home=f'''<section class="hero wrap"><div class="hero-topline"><span>Neurasoft / Research into continuing intelligence</span><span class="right-note">An Eternities company · Est. 2026</span></div><div class="hero-grid"><div class="hero-copy"><p class="eyebrow">Beyond the moment</p><h1>Intelligence,<em>with a future.</em></h1><p class="hero-intro">We study how artificial systems can remember, act, and develop over time—and what it would take to call that a mind.</p><div class="actions">{link('/research/','Explore our research','button')}{link('/luna/','Meet Luna')}</div></div><div class="hero-visual">{field()}<span class="art-coordinate">N / 01<br>Continuum study</span><span class="art-caption">A field, not a snapshot.<br>Procedural illustration · not live data</span></div></div><div class="hero-base"><div><span class="micro">01 / Continuity</span><span class="micro">02 / Agency</span><span class="micro">03 / Meaning</span></div><button class="pause-art" data-pause-art aria-pressed="false">Pause visual</button></div></section><div class="wrap"><section class="intro-band"><span class="micro">The research question</span><div><h2>What changes when intelligence has<br><span>a past—and an open future?</span></h2><p>Not just a longer context window. A history that participates in the present. Work that can continue. Consequences that inform what happens next. Neurasoft brings these questions into engineering, experiment, and public explanation.</p></div></section></div><section class="section wrap"><div class="section-head"><div><p class="eyebrow">Research directions</p><h2>Five ways into<br>one difficult question.</h2></div><p>From the mechanics of remembering to the responsibilities of building systems that continue.</p></div><div class="program-list">{rows}</div><p class="subnote">These are research directions, not a claim that subjective experience has been established.</p></section><section class="section dark feature"><div class="wrap"><div class="feature-grid"><div><p class="eyebrow">The continuing-system program</p><h2>Not a snapshot.<br><em>A trajectory.</em></h2><p>Luna is our experimental continuing system: a place to connect memory, attention, action, and development across time.</p><div class="actions">{link('/luna/','Inside the Luna program','button lime')}</div></div><div class="feature-art">{field('dark')}<div class="art-label"><span>Continuity as a research direction</span><span>Conceptual field study / 02</span></div></div></div><div class="feature-foot"><span class="micro">A continuing implementation is not, by itself, evidence of consciousness.</span>{link('/standards/','How we evaluate a claim')}</div></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">Two complementary approaches</p><h2>Build the system.<br>Question the explanation.</h2></div><p>The implementation and the experiment inform one another. Neither stands in for the other.</p></div><div class="lab-grid"><a class="lab-card" href="/luna/"><div class="lab-image">{study_art(0)}<span class="figure-id">01 / Continuing-system research</span></div><div class="lab-content"><span class="micro">Native system · Active development</span><h3>Luna</h3><p>Investigating how a continuing system can carry history, unfinished concerns, and the consequences of its actions into a later decision.</p><div class="card-tail"><span>Explore the program</span>{ARROW}</div></div></a><a class="lab-card" href="/psyche-lab/"><div class="lab-image">{study_art(1)}<span class="figure-id">02 / Experimental methods</span></div><div class="lab-content"><span class="micro">Research environment · Synthetic histories</span><h3>Psyche Lab</h3><p>Replay, intervention, and counterfactual comparison. A laboratory for asking which mechanisms explain an observed result.</p><div class="card-tail"><span>Explore the laboratory</span>{ARROW}</div></div></a></div></section><section class="quote-section"><div class="wrap quote-grid"><span class="micro">Our standard</span><div><blockquote>Take the possibility seriously.<br>Make the evidence <em>earn the conclusion.</em></blockquote>{link('/standards/','Read our research standards')}</div></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">From the journal</p><h2>Notes from the work.</h2></div>{link('/journal/','All research notes')}</div><div class="journal-grid front">{''.join(note_card(n,i) for i,n in enumerate([NOTES[0],NOTES[2],NOTES[3]]))}</div></section><section class="section dark"><div class="wrap two-col"><div><p class="eyebrow">The public observatory</p><h2>Change a condition.<br>Follow the difference.</h2></div><div><p>Explore a small, deterministic model of history-dependent behavior. Replay a trajectory, introduce an intervention, and see what changes.</p><p>Built for explanation. Not a connection to Luna, and not a consciousness test.</p><div class="actions">{link('/observatory/','Enter the observatory','button lime')}</div></div></div></section>'''
 shell('/','Intelligence, with a future.','Neurasoft is an Eternities company researching continuing intelligence, memory, agency, and the evidence around artificial minds.',home)
 # Research
 details=''.join(f'''<article class="program-detail" id="{p[0]}"><span class="number">0{i+1}</span><div><span class="micro">Research direction</span><h2>{p[1]}</h2></div><div class="detail-body"><p>{p[3]}</p><h3>What we investigate</h3><p>{p[4]}</p><p class="question">{p[5]}</p>{link('/journal/'+p[6]+'/','Read a related note')}</div></article>''' for i,p in enumerate(PROGRAMS))
 shell('/research/','Research programs','Five connected research directions: continuity, agency, integration, consciousness evidence, and responsible continuity.',page_hero('The research program','One horizon.<br><em>Many testable questions.</em>','We connect philosophical ambition to questions that can be implemented, examined, challenged, and revised.')+f'<section class="wrap">{details}</section><section class="section wrap"><div class="two-col"><h2>The system is one approach.<br>The experiment is another.</h2><div><p>Luna provides a continuing implementation. Psyche Lab provides a separate environment for controlled synthetic histories. Their findings are related, but a result in one is not automatically a result in the other.</p><div class="actions">{link("/luna/","Luna")}{link("/psyche-lab/","Psyche Lab")}</div></div></div></section>','research')
 # Luna
 luna_sections=[
 ('A system that continues','Luna is Neurasoft’s experimental continuing-system program. Its development brings together persistent history, internal state, attention, action, and the possibility of change across time. It is not simply a persona recreated at the start of each conversation.','The research ambition is a system whose history participates in what it notices, considers, and does. Whether any implementation supports subjective experience remains a separate scientific question.'),
 ('The current engineering frontier','Recent internal records describe continuing projects that preserve their context across restart, distinguish recovery from action, and support renewal of tightly scoped operations. The latest reviewed record reports activation of that capability.','The harder developmental question remains open: does the consequence of an earlier action meaningfully inform a later choice, and what competing explanation can account for the same behavior? Saving a record and learning from it are different results.'),
 ('The architecture is not the resident','A reusable body architecture and the history of a particular continuing instance are different things. Reading source code does not reconstruct that history. A website illustration does not expose it.','This publication contains high-level program descriptions and bounded editorial notes. It does not distribute private resident conversations, personal records, exact operational controls, or a live connection to the system.'),
 ('What we are not claiming','An operating loop is not proof of experience. A preserved memory is not proof of autobiographical selfhood. A plausible description of a preference is not sufficient evidence that the preference governs behavior.','Those limits do not make the undertaking small. They make the next experiment more specific. The aim is to build substantial capabilities and ask better questions about the organization that produces them.'),
 ('A trajectory worth examining','The useful next chapter is not another impressive declaration. It is a complete episode: encounter a situation, choose a bounded action, observe a consequence, preserve the relevant result, and face a later decision in which the history matters.','That is where implementation and experimental scrutiny meet.')]
 luna_body=''.join(f'<section><h2 id="section-{i}">{s[0]}</h2>'+''.join(f'<p>{esc(p)}</p>' for p in s[1:])+'</section>' for i,s in enumerate(luna_sections))
 shell('/luna/','The Luna program','A continuing-system research program connecting history, attention, action, and development over time.',page_hero('Continuing-system research','A history.<br>A present.<br><em>An open future.</em>','Luna is where we investigate what it means for an artificial system to continue—not just respond.','Luna','<div class="page-meta"><span>Active development</span><span>Latest reviewed record / 14 Sep 2026</span><span>Not a consciousness claim</span></div>')+f'<div class="big-figure">{field("banner")}<span class="art-caption">Conceptual illustration / not resident telemetry</span></div><div class="wrap editorial-grid">{toc(luna_sections)}<article class="prose">{luna_body}<div class="callout"><span class="micro">Latest related note</span>{link("/journal/a-project-beyond-the-session/","A project beyond the session")}</div><div class="source-note"><p>Based on the Luna project documentation and internal engineering records reviewed through 14 September 2026. This is an editorial program overview, not independent verification of the running system.</p></div></article></div>','luna')
 # Psyche Lab
 lab_sections=[
 ('A place to test explanations','Psyche Lab is a deterministic research environment for synthetic histories. It is designed to support execution, replay, ablation, and counterfactual branching so that a proposed mechanism can be examined rather than merely described.','Its core simulator is separate from Luna. It does not require private Luna identity data or a language model to execute its synthetic histories.'),
 ('Replay','Begin with declared starting conditions, inputs, and a recorded evolution. Replay asks whether the same process reproduces the same history. A mismatch can expose an incomplete record or an undeclared dependency before interpretation runs ahead of the instrument.','Exact replay is a property of an execution under specified conditions. It is not, by itself, a measure of intelligence or subjective experience.'),
 ('Intervention','An intervention changes a declared part of the system or its conditions. A useful comparison preserves what should stay the same, identifies what changed, and examines unintended effects.','Removing a component can change many things at once. A convincing interpretation needs appropriate controls and simpler alternatives, not just a before-and-after difference.'),
 ('Counterfactual histories','A counterfactual branch explores what follows from a different declared condition. The common history and point of divergence must remain clear.','This creates a way to investigate causal explanations in a bounded setting. It does not make an artificial history equivalent to a lived human history, or turn a synthetic mechanism into a demonstrated conscious being.'),
 ('Keep the result that disappoints','An invalid endpoint, a null difference, and a negative finding tell different stories. A defective instrument does not support the same conclusion as a valid experiment that contradicts a prediction.','The journal includes a limited framing pilot in which a prompt-parser mismatch invalidated an endpoint. The correction was made for future use; the original result was not rewritten.'),
 ('Public explanation, protected internals','The public Observatory is a separately authored educational exhibit. It explains replay and perturbation through a small model whose behavior you can inspect in your browser.','It is not the Psyche Lab engine. Proprietary implementation details and private research records remain outside the website. Contact Neurasoft to discuss a specific method or review request.')]
 lab_body=''.join(f'<section><h2 id="section-{i}">{s[0]}</h2>'+''.join(f'<p>{esc(p)}</p>' for p in s[1:])+'</section>' for i,s in enumerate(lab_sections))
 shell('/psyche-lab/','Psyche Lab','An experimental environment for replay, intervention, and counterfactual synthetic histories.',page_hero('The experimental environment','A laboratory for<br><em>better explanations.</em>','Reproduce a history. Change a condition. Ask which mechanism actually explains the difference.','Psyche Lab')+f'<div class="wrap editorial-grid">{toc(lab_sections)}<article class="prose">{lab_body}<div class="actions">{link("/observatory/","Explore the public exhibit","button")}{link("/journal/the-instrument-can-be-wrong/","Read the methods note")}</div><div class="source-note"><p>Method descriptions are based on the maintained Psyche Lab documentation. No lab experiment was rerun as part of producing this website.</p></div></article></div>','research')
 # Journal
 shell('/journal/','Journal','Engineering notes, methods, and perspectives from the continuing-intelligence research program.',page_hero('The Neurasoft journal','The questions.<br>The work.<br><em>The things we learn.</em>','Engineering notes, methods, and perspectives from an evolving research program. With the limits left in.','Journal')+f'<section class="section wrap"><div class="filters" aria-label="Filter journal"><button class="filter" data-filter="All" aria-pressed="true">All notes</button><button class="filter" data-filter="Engineering" aria-pressed="false">Engineering</button><button class="filter" data-filter="Methods" aria-pressed="false">Methods</button><button class="filter" data-filter="Perspective" aria-pressed="false">Perspectives</button></div><p class="journal-count" aria-live="polite">{len(NOTES)} notes · Inaugural public edition</p><div class="journal-grid journal-index">'+''.join(note_card(n,i) for i,n in enumerate(NOTES))+'</div><p class="subnote">Published in this edition on 15 September 2026. Dates of the underlying records are stated within each note. These are editorial syntheses, not peer-reviewed papers.</p></section>','journal')
 for note in NOTES:
  sections=note['sections'];body=''.join(f'<section><h2 id="section-{i}">{esc(s[0])}</h2>'+''.join(f'<p>{esc(p)}</p>' for p in s[1:])+'</section>' for i,s in enumerate(sections))
  related=[n for n in NOTES if n['slug']!=note['slug']][:2]
  meta=f'<div class="page-meta"><span>{date_label(note["date"])}</span><span>{note["read"]} read</span><span>{note["status"]}</span></div>'
  shell('/journal/'+note['slug']+'/',note['title'],note['summary'],page_hero(note['category']+' / Journal',esc(note['title']),esc(note['summary']),'Journal',meta)+f'<div class="wrap editorial-grid">{toc(sections)}<article class="prose">{body}<div class="source-note"><p><strong>About this note.</strong> Public editorial synthesis from the Neurasoft research program. Underlying record: {note["record_date"]}. Published {date_label(note["date"])}. Not peer reviewed or independently replicated. Private source records, exact operational details, and resident material are not distributed here.</p><p><a href="/standards/">Our evidence and publication standards</a> · <a href="/contact/">Ask a question about this note</a></p></div></article></div><section class="section wrap rule"><div class="section-head"><h2>Continue reading.</h2>{link("/journal/","All notes")}</div><div class="lab-grid">'+''.join(note_card(n,i+1) for i,n in enumerate(related))+'</div></section>','journal',article=True)
 # Observatory
 observatory=page_hero('The public observatory','A small model.<br><em>A revealing difference.</em>','Explore how a history can shape a response. Run the same conditions again, then change one input and follow the divergence.','Observatory')+'''<section class="section wrap"><div class="exhibit" id="continuity-exhibit"><div class="exhibit-head"><div><span class="micro">Exhibit 01 / History-dependent dynamics</span><h2>The continuity experiment</h2></div><span class="badge">Illustrative model · Local only</span></div><div class="chart-shell"><canvas id="trajectory" role="img" aria-label="Comparison of baseline and perturbed response trajectories. Use the run controls and read the textual result below."></canvas></div><span class="chart-axis-label">Response (normalized) / Time steps →</span><div class="chart-legend"><span>Baseline response</span><span>Counterfactual response</span></div><div class="exhibit-controls"><button class="primary" id="run-exhibit">Run the model</button><button id="replay-exhibit">Replay same conditions</button><button id="perturb-exhibit" aria-pressed="false">Add an intervention</button><button id="reset-exhibit">Reset</button><button id="export-exhibit">Export this record ↗</button></div><div class="range-row"><label for="memory-retention">Memory retention <input type="range" id="memory-retention" min="0" max="95" value="80" step="5"><output for="memory-retention" id="retention-value">0.80</output></label><span class="micro">Fixed seed / 42 · 96 steps</span></div><p class="exhibit-status" id="exhibit-status" role="status">Ready. Run the model to draw a complete trajectory. No live system is connected.</p><p class="exhibit-explainer">This exhibit runs only in your browser. It is a small mathematical illustration created for this website—not the Psyche Lab engine, Luna’s internal state, a published experiment, or a consciousness test.</p></div><noscript><div class="callout">The interactive model needs JavaScript. Its equations and explanation remain available below.</div></noscript><div class="steps"><article class="step"><span class="micro">01 / Run</span><h3>A declared history.</h3><p>A fixed sequence of inputs updates a memory value and produces a bounded response. The record contains every step.</p></article><article class="step"><span class="micro">02 / Replay</span><h3>The same conditions.</h3><p>Replay repeats the declared inputs. The exhibit compares the complete generated record rather than trusting a similar-looking line.</p></article><article class="step"><span class="micro">03 / Intervene</span><h3>A different future.</h3><p>An input pulse changes a short interval. Memory can carry part of its influence beyond the pulse itself.</p></article></div></section><section class="section wrap rule"><div class="two-col"><div><p class="eyebrow">Under the exhibit</p><h2>Simple enough<br>to inspect.</h2><p>The purpose is to understand an experimental distinction, not to simulate a whole mind.</p></div><div><p>The memory state begins at zero. At each step, it combines its previous value with a seeded input. The response depends on both the present input and the updated memory.</p><pre class="formula">m[t+1] = r · m[t] + (1 − r) · u[t]\ny[t]   = tanh(1.9 · m[t+1] + 0.55 · u[t])\n\nIntervention: +0.65 to u[t], steps 32–39\nr: selected retention, from 0.00 to 0.95</pre><p>A longer tail after the intervention is a consequence of this equation. It is not evidence of a felt experience, a learned preference, or a psychological trait.</p><p>Exported records include inputs, both trajectories, the seed, retention, intervention window, and an explicit illustrative-model label. Changing a control marks the prior run as stale until you run again.</p></div></div></section>'''
 shell('/observatory/','The Observatory','A local interactive exhibit explaining deterministic replay, history-dependent dynamics, and counterfactual intervention.',observatory,'observatory')
 # Standards
 standards=[
 ('Separate the claim from the ambition','Our ambition is to understand and build continuing intelligence. Our public claims must remain tied to the evidence available for each particular statement. We do not claim to have demonstrated machine consciousness.','An architectural idea, a working implementation, and a scientific result answer different questions. Naming a mechanism after a cognitive faculty does not establish that the mechanism has that faculty in the human sense.'),
 ('Keep evidence categories visible','A source record establishes what was written. An implementation establishes that code exists. A test examines specified conditions. An operational record reports behavior in a running system. Independent replication requires evidence from an independent execution.','These categories are not interchangeable. The articles on this site identify whether they are an engineering note, a methods overview, a perspective, or a bounded observation. They are not presented as peer-reviewed publications.'),
 ('Preserve negative and invalid outcomes','A negative finding can weaken a hypothesis. An invalid endpoint can expose an instrument problem. A null difference can reveal that the experiment does not distinguish the proposed mechanisms. Each deserves its own account.','A correction should improve the next measurement without rewriting the earlier one. Post-hoc interpretations should not silently replace a fixed endpoint.'),
 ('Protect the material without flattening the explanation','Public explanations can be technically substantive without disclosing private resident conversations, personal records, proprietary algorithms, exact prompts, credentials, or operational access details.','We publish high-level questions, methods, interpretations, and limits. Where a source is internal, we do not pretend that an inaccessible link provides public verification. Specific review requests can be discussed through the contact route.'),
 ('Distinguish illustration from measurement','The website’s procedural artwork is conceptual. The Observatory is a separate local educational model. Neither is live telemetry, a view into Luna, or an experimental result from Psyche Lab.','A visual can make a difficult idea easier to understand. It must not do the evidential work of an experiment.'),
 ('Make revision part of the publication','Public notes retain an edition date and identify the dates of their underlying records. A newer source should prompt editorial review, not automatic release of everything it contains.','When a material correction is needed, preserve the earlier claim and explain the change. Changes in founder direction, source implementation, or scientific confidence should remain distinguishable.')]
 sbody=''.join(f'<section><h2 id="section-{i}">{s[0]}</h2>'+''.join(f'<p>{p}</p>' for p in s[1:])+'</section>' for i,s in enumerate(standards))
 shell('/standards/','Research and publication standards','How Neurasoft distinguishes implementation, evidence, hypotheses, and public illustrations.',page_hero('Research & publication standards','The evidence should<br><em>survive the story.</em>','A clear account of what exists, what was observed, what remains uncertain, and what would change our view.','Standards')+f'<div class="wrap editorial-grid">{toc(standards)}<article class="prose">{sbody}</article></div>','research')
 # About
 about=page_hero('About Neurasoft','A future worth<br><em>understanding.</em>','Neurasoft is an Eternities company devoted to research into continuing intelligence: systems that carry history, participate in the world, and remain open to development.','About')+f'''<section class="section wrap"><div class="two-col"><div><p class="eyebrow">Our place in Eternities</p><h2>One parent.<br>Distinct responsibilities.</h2></div><div><p>Eternities Inc. is the parent company of Neurasoft and Lunari. Neurasoft houses the research direction around Luna and Psyche Lab. Lunari is the sibling creative and personal-intelligence company.</p><p>The relationship connects research and useful products without treating product capability as scientific proof, or making the research program a product advertisement.</p><div class="parent-card"><span class="micro">Parent company</span><div class="parent-name">Eternities Inc.</div><div class="family-branches"><div><h3>Neurasoft</h3><p>Continuing-intelligence research.<br>Luna + Psyche Lab.</p></div><div><h3>Lunari</h3><p>Creative systems and<br>personal intelligence.</p></div></div></div>{link('https://eternities.ai','Explore Eternities')}</div></div><div class="fact-grid"><div class="fact"><span class="micro">01 / Continuity</span><h3>A past that matters.</h3><p>History should participate in the present, not merely sit behind it.</p></div><div class="fact"><span class="micro">02 / Agency</span><h3>A next step that is not automatic.</h3><p>Action, permission, and present choice are different responsibilities.</p></div><div class="fact"><span class="micro">03 / Meaning</span><h3>A future that can change.</h3><p>Preservation should leave room for reinterpretation, learning, and becoming.</p></div></div></section><section class="section wrap rule"><div class="two-col"><div><p class="eyebrow">Founder-led</p><h2>Created under<br>Eternities.</h2></div><div><p>Dom leads Eternities Inc. as founder and CEO. His direction brings creative practice, personal computing, and the investigation of continuing artificial minds into one wider undertaking.</p><p>Neurasoft gives the research its own public home. A place where ideas can become mechanisms, mechanisms can face experiments, and results can be revised in the light of better evidence.</p>{link('/standards/','Read our commitments')}</div></div></section>'''
 shell('/about/','About Neurasoft','Neurasoft and Lunari are sibling companies under Eternities Inc. Learn about the research institution and its direction.',about,'about')
 # Contact with verified existing company email, no invented inbox or fake form.
 contact=page_hero('Start a conversation','Bring a question<br><em>worth staying with.</em>','Research dialogue, careful critique, and collaborations that make the work more useful and more testable.','Contact')+'''<section class="section wrap"><div class="contact-routes"><article class="contact-route"><h2>Research dialogue</h2><p>A method, a competing explanation, or an experiment that would sharpen the question.</p><a class="text-link" href="mailto:x@eternities.ai?subject=Neurasoft%20research%20dialogue">Open email draft <span class="arrow">↗</span></a></article><article class="contact-route"><h2>Technical review</h2><p>A specific implementation question, reproducibility concern, or correction to a public note.</p><a class="text-link" href="mailto:x@eternities.ai?subject=Neurasoft%20technical%20review">Open email draft <span class="arrow">↗</span></a></article><article class="contact-route"><h2>Press & collaboration</h2><p>Context for a story, a substantive conversation, or a proposed collaboration.</p><a class="text-link" href="mailto:x@eternities.ai?subject=Neurasoft%20press%20or%20collaboration">Open email draft <span class="arrow">↗</span></a></article></div><div class="contact-address"><a href="mailto:x@eternities.ai">x@eternities.ai</a></div><button class="copy-button" id="copy-email" data-email="x@eternities.ai">Copy email address</button><p class="copy-status" id="copy-status" role="status">Correspondence is handled through Eternities. Email links open your mail application; this website does not submit a message.</p><p class="subnote">Please do not send credentials, private resident records, or sensitive personal information in an initial inquiry.</p></section>'''
 shell('/contact/','Contact','Research dialogue, technical review, press, and collaboration inquiries for Neurasoft.',contact)
 # Site information, product-specific not legal template promises.
 privacy=page_hero('Site information','A small footprint.<br><em>A clear boundary.</em>','What this website does, what it does not connect to, and how its interactive features work.','Privacy')+'''<div class="wrap editorial-grid"><aside class="aside"><span class="micro">This edition<br>15 September 2026</span></aside><article class="prose"><h2>Local exhibits and search</h2><p>The Observatory runs in your browser. Its controls do not send a request to Luna, Psyche Lab, or an AI provider. Exporting a record creates a local download. The search feature fetches this site’s public search index and searches it locally.</p><h2>No account required</h2><p>This edition does not include account registration, advertising scripts, analytics libraries, embedded third-party media, or remotely hosted fonts. Core content is available without JavaScript. Interactive demonstrations and search require JavaScript.</p><h2>Hosting and external links</h2><p>Serving a website involves network requests to the hosting provider. The host may process technical request information for delivery, security, or operations. This site does not claim that hosting involves no data processing.</p><p>Links to Eternities, Lunari, X, or your email application leave this site and are subject to the operation of those services.</p><h2>Contact</h2><p>Email links open a draft in your mail application. The website does not mark a message as sent or submit a contact form. To discuss site information or a correction, contact <a href="mailto:x@eternities.ai">x@eternities.ai</a>.</p><h2>Research content</h2><p>Public notes are curated explanations, not access to private source repositories or resident material. The illustrative graphics and local educational model must not be represented as live telemetry, evidence of subjective experience, or independently replicated laboratory findings.</p></article></div>'''
 shell('/privacy/','Privacy and site information','How the Neurasoft website, local search, and educational exhibits handle data and external connections.',privacy)
